// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address payable nonOwner;

    function setUp() public { c = new SimpleWallet(); nonOwner = payable(address(0xBEEF)); }

    function testFuzz_property(uint256 sendValue, uint256 fundAmount) public {
        sendValue = bound(sendValue, 0, 1 ether);
        fundAmount = bound(fundAmount, 0, 1 ether);

        vm.deal(nonOwner, fundAmount);

        if (fundAmount > 0) {
            vm.deal(address(this), fundAmount);
            (bool s,) = address(c).call{value: fundAmount}("");
            require(s);
        }

        vm.prank(address(this));
        bool ok;
        try c.sendMoney(nonOwner, sendValue) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        vm.prank(nonOwner);
        bool nonOwnerCouldWithdraw;
        try c.withdrawAll() {
            nonOwnerCouldWithdraw = true;
        } catch {
            nonOwnerCouldWithdraw = false;
        }

        assertTrue(!nonOwnerCouldWithdraw);
    }
}
